(function() {
    'use strict';

    class AgilAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'El Ágil';
            this.version = '1.2.0';
            this.ROUNDS = [
                {
                    nameEn: 'The Agile Model',
                    nameEs: 'El Modelo Agil',
                    descEn: '<b>March 2026 — CTO Leadership Offsite, Valle de Bravo.</b><br><br>Pago Claro just closed a Series B (MXN 480M). The board expects 2x revenue by end of 2027 (MXN 624M). But engineering coordination is breaking down at 68 engineers across 6 squads.<br><br><b>Three critical incidents in Q1 2026:</b><br>1. Squad Alpha shipped a payment routing change that broke Squad Gamma mobile SDK — 6-hour outage, MXN 8.7M transactions blocked<br>2. Squads Beta and Delta independently built duplicate notification systems — MXN 3.2M/year wasted<br>3. Quarterly roadmap planning took 14 days and was partially obsolete on Day 1<br><br><b>CTO Sofia Mendoza</b> favors the Spotify model. <b>CPO Jorge Saavedra</b> favors SAFe. <b>Head of Engineering Rodrigo Castellanos</b> argues for a custom hybrid.<br><br>Choose your scaling framework, set your implementation budget, and decide whether to create a platform team. Also select which DORA metric to prioritize.',
                    descEs: '<b>Marzo 2026 — Retiro de liderazgo CTO, Valle de Bravo.</b><br><br>Pago Claro acaba de cerrar una Serie B (MXN 480M). El consejo espera 2x de ingresos para fin de 2027 (MXN 624M). Pero la coordinacion de ingenieria se rompe con 68 ingenieros en 6 squads.<br><br><b>Tres incidentes criticos en Q1 2026:</b><br>1. Squad Alpha envio un cambio de enrutamiento de pagos que rompio el SDK movil de Squad Gamma — 6 horas de caida, MXN 8.7M en transacciones bloqueadas<br>2. Squads Beta y Delta construyeron sistemas de notificacion duplicados — MXN 3.2M/anio desperdiciados<br>3. La planificacion trimestral de roadmap tomo 14 dias y fue parcialmente obsoleta el Dia 1<br><br><b>CTO Sofia Mendoza</b> prefiere el modelo Spotify. <b>CPO Jorge Saavedra</b> prefiere SAFe. <b>Head of Engineering Rodrigo Castellanos</b> argumenta por un hibrido personalizado.<br><br>Elige tu marco de escalamiento, establece tu presupuesto de implementacion y decide si crear un equipo de plataforma. Tambien selecciona que metrica DORA priorizar.'
                },
                {
                    nameEn: 'The Team in Crisis',
                    nameEs: 'El Equipo en Crisis',
                    descEn: '<b>Squad Gamma Performance Crisis — Mobile SDK v4.0</b><br><br>The SDK v4.0 has been in development 14 months (planned: 8). It is 6 months late.<br><br><b>Impact:</b><br>- 12 mid-market clients delayed mobile expansion — MXN 28M ARR at risk<br>- Competitor Bolt launched their SDK v3 in January — already captured 3 Pago Claro prospects<br>- Squad velocity dropped 40% in last 3 sprints<br>- Code coverage: 34% (target: 80%); 127 open bugs (41 critical)<br><br><b>The Mariana Ruiz situation:</b> Tech lead, 24 months without rotation, showing burnout. Has received offers from Google and Nubank. Replacement cost: MXN 3.2M. Attrition probability if ignored: ~65%.<br><br><b>Cost of Delay:</b> MXN 6.8M/month (MXN 2.33M delayed revenue + MXN 4.5M competitive loss)<br><br>Choose your turnaround strategy and decide how to handle your key talent.',
                    descEs: '<b>Crisis de Rendimiento de Squad Gamma — SDK Movil v4.0</b><br><br>El SDK v4.0 lleva 14 meses en desarrollo (planificado: 8). Tiene 6 meses de retraso.<br><br><b>Impacto:</b><br>- 12 clientes mid-market retrasaron expansion movil — MXN 28M ARR en riesgo<br>- Competidor Bolt lanzo su SDK v3 en enero — ya capturo 3 prospectos de Pago Claro<br>- Velocidad del squad cayo 40% en ultimos 3 sprints<br>- Cobertura de tests: 34% (objetivo: 80%); 127 bugs abiertos (41 criticos)<br><br><b>Situacion de Mariana Ruiz:</b> Tech lead, 24 meses sin rotacion, muestra agotamiento. Ha recibido ofertas de Google y Nubank. Costo de reemplazo: MXN 3.2M. Probabilidad de salida si se ignora: ~65%.<br><br><b>Costo de Demora:</b> MXN 6.8M/mes (MXN 2.33M ingresos retrasados + MXN 4.5M perdida competitiva)<br><br>Elige tu estrategia de rescate y decide como manejar tu talento clave.'
                },
                {
                    nameEn: 'Debt and Regulation',
                    nameEs: 'La Deuda y la Regla',
                    descEn: '<b>CNBV Regulatory Deadline + Tech Debt Reckoning</b><br><br>CNBV Circular 3/2026 mandates:<br>1. Real-time AML detection with ML — deadline Sept 30, 2026 (6 months)<br>2. Open Finance API (SPEI 3.0) — deadline Dec 31, 2026<br>3. Biometric KYC — deadline March 31, 2027<br><br><b>Regulatory cost:</b> MXN 17.8M + 38 engineer-months<br><br><b>Tech debt (score 62/100):</b><br>- Merchant dashboard: React 16 (EOL 2023) — 3 months to upgrade, +15% performance<br>- Payment core: 3 God tables (247 columns), queries averaging 340ms (target: <100ms)<br>- Test coverage: 34% mobile, 51% core, 68% dashboard<br>- Remediation cost: 16 engineer-months (MXN 4.8M) for 18-22% velocity gain (equivalent to 12-15 extra engineers)<br>- ROI: ~798% | Payback: 1.3 months<br><br><b>The constraint:</b> Net capacity is 346.8 engineer-months. But squads are NOT fungible — Alpha is needed for AML + SPEI + tech debt + roadmap. Map your allocation carefully.<br><br>Allocate engineer-months across all workstreams. Watch the total.',
                    descEs: '<b>Fecha Limite Regulatoria CNBV + Ajuste de Deuda Tecnica</b><br><br>Circular CNBV 3/2026 exige:<br>1. Deteccion AML en tiempo real con ML — plazo 30 sept 2026 (6 meses)<br>2. API Open Finance (SPEI 3.0) — plazo 31 dic 2026<br>3. KYC Biometrico — plazo 31 mar 2027<br><br><b>Costo regulatorio:</b> MXN 17.8M + 38 meses-ingeniero<br><br><b>Deuda tecnica (score 62/100):</b><br>- Dashboard de comercios: React 16 (fin de vida 2023) — 3 meses para actualizar, +15% rendimiento<br>- Core de pagos: 3 tablas God (247 columnas), consultas promedio 340ms (objetivo: <100ms)<br>- Cobertura de tests: 34% movil, 51% core, 68% dashboard<br>- Costo de remediacion: 16 meses-ingeniero (MXN 4.8M) para 18-22% ganancia de velocidad (equivalente a 12-15 ingenieros extra)<br>- ROI: ~798% | Recuperacion: 1.3 meses<br><br><b>La restriccion:</b> Capacidad neta es 346.8 meses-ingeniero. Pero los squads NO son intercambiables — Alpha se necesita para AML + SPEI + deuda tecnica + roadmap. Mapea tu asignacion con cuidado.<br><br>Asigna meses-ingeniero a cada flujo de trabajo. Vigila el total.'
                },
                {
                    nameEn: 'The Acquisition',
                    nameEs: 'La Adquisicion',
                    descEn: '<b>Build vs. Buy vs. Partner: DataLens AI Decision</b><br><br><b>DataLens AI</b> offers 100% acquisition at MXN 180M:<br>- 8 engineers (4 ML, 2 backend, 2 data)<br>- ML fraud detection: claims 94.2% accuracy vs. Pago Claro current 87.3% (rule-based)<br>- Revenue: MXN 4.2M ARR | Net loss: -MXN 28M<br>- Revenue multiple: 42.9x ARR (very high)<br>- Acqui-hire value: MXN 64M (8 engineers x MXN 8M) | IP premium: MXN 116M<br><br><b>Fraud impact:</b> Current losses MXN 12.4M/year. If 94.2% accuracy: ~MXN 7.8M = MXN 4.6M/year savings<br><br><b>Hidden optionality:</b> DataLens 4 ML engineers could handle AML regulatory requirement — freeing 12 Alpha engineer-months<br><br><b>DATA PROVENANCE RISK:</b> Training data is 24M records from a regional bank — licensing unclear. Under LFPDPPP + CNBV, acquiring improperly licensed data = up to 5% revenue fine (MXN 15.6M) + model destruction order.<br><br><b>Partner option:</b> License at MXN 2.8M/year + option to acquire at MXN 120M in 18 months (after due diligence)<br><br>Choose your strategy and risk mitigation approach.',
                    descEs: '<b>Build vs. Buy vs. Partner: Decision DataLens AI</b><br><br><b>DataLens AI</b> ofrece adquisicion del 100% por MXN 180M:<br>- 8 ingenieros (4 ML, 2 backend, 2 datos)<br>- Deteccion de fraude ML: afirma 94.2% precision vs. 87.3% actual de Pago Claro (basado en reglas)<br>- Ingresos: MXN 4.2M ARR | Perdida neta: -MXN 28M<br>- Multiplo de ingresos: 42.9x ARR (muy alto)<br>- Valor acqui-hire: MXN 64M (8 ingenieros x MXN 8M) | Prima de IP: MXN 116M<br><br><b>Impacto en fraude:</b> Perdidas actuales MXN 12.4M/anio. Si 94.2% precision: ~MXN 7.8M = MXN 4.6M/anio de ahorro<br><br><b>Opcionalidad oculta:</b> Los 4 ingenieros ML de DataLens podrian cubrir el requerimiento regulatorio AML — liberando 12 meses-ingeniero de Alpha<br><br><b>RIESGO DE PROVENIENCIA DE DATOS:</b> Los datos de entrenamiento son 24M registros de un banco regional — licenciamiento no claro. Bajo LFPDPPP + CNBV, adquirir datos con licencia impropia = multa de hasta 5% ingresos (MXN 15.6M) + orden de destruccion del modelo.<br><br><b>Opcion de partnership:</b> Licencia a MXN 2.8M/anio + opcion de compra a MXN 120M en 18 meses (post due diligence)<br><br>Elige tu estrategia y enfoque de mitigacion de riesgos.'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 480,
                    engineeringCapacity: 346.8,
                    techDebtScore: 62,
                    revenueRunRate: 312,
                    doraComposite: 25,
                    sdkDelayMonths: 6,
                    fraudLosses: 12.4,
                    marianaRetained: true,
                    regulatoryCompliance: 0,
                    velocityMultiplier: 1.0,
                    cashHistory: [],
                    revenueHistory: [],
                    capacityUsed: [],
                    capacityRemaining: [],
                    investmentTotal: 0,
                    sdkStatus: 'delayed'
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    scalingModel: 'custom',
                    frameworkBudget: 3,
                    platformTeam: true,
                    doraTarget: 'mttr',
                    gammaOption: 'B',
                    marianaAction: 'rotate',
                    testCoverageSprint: false,
                    allocReg: 38,
                    allocDebt: 16,
                    allocSdk: 18,
                    allocRoadmap: 60,
                    allocBau: 28,
                    datalensOption: 'partner',
                    dueDiligence: true,
                    hireML: false,
                    explainability: false
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var st = window.mySimulation.state;
            var round = st.currentPeriod;

            if (round === 1) {
                var modelSel = document.getElementById('scalingModelSelect');
                if (modelSel) decisions.scalingModel = modelSel.value;
                var budgetIn = document.getElementById('frameworkBudgetInput');
                if (budgetIn) decisions.frameworkBudget = parseFloat(budgetIn.value);
                var ptCheck = document.getElementById('platformTeamCheck');
                if (ptCheck) decisions.platformTeam = ptCheck.checked;
                var doraSel = document.getElementById('doraTargetSelect');
                if (doraSel) decisions.doraTarget = doraSel.value;
                if (!decisions.frameworkBudget || decisions.frameworkBudget < 0 || decisions.frameworkBudget > 10) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('budget_warning'), 'warning');
                    return false;
                }
            } else if (round === 2) {
                var gammaSel = document.getElementById('gammaOptionSelect');
                if (gammaSel) decisions.gammaOption = gammaSel.value;
                var marianaSel = document.getElementById('marianaActionSelect');
                if (marianaSel) decisions.marianaAction = marianaSel.value;
                var tcCheck = document.getElementById('testCoverageCheck');
                if (tcCheck) decisions.testCoverageSprint = tcCheck.checked;
            } else if (round === 3) {
                var regIn = document.getElementById('allocRegInput');
                if (regIn) decisions.allocReg = parseFloat(regIn.value);
                var debtIn = document.getElementById('allocDebtInput');
                if (debtIn) decisions.allocDebt = parseFloat(debtIn.value);
                var sdkIn = document.getElementById('allocSdkInput');
                if (sdkIn) decisions.allocSdk = parseFloat(sdkIn.value);
                var roadIn = document.getElementById('allocRoadmapInput');
                if (roadIn) decisions.allocRoadmap = parseFloat(roadIn.value);
                var bauIn = document.getElementById('allocBauInput');
                if (bauIn) decisions.allocBau = parseFloat(bauIn.value);

                var total = decisions.allocReg + decisions.allocDebt + decisions.allocSdk + decisions.allocRoadmap + decisions.allocBau;
                if (total > 346.8) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('capacity_warning'), 'warning');
                    return false;
                }
                if (decisions.allocReg < 38) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('reg_minimum_warning'), 'warning');
                    return false;
                }
                if (decisions.allocBau < 28) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('bau_minimum_warning'), 'warning');
                    return false;
                }
            } else if (round === 4) {
                var dlSel = document.getElementById('datalensOptionSelect');
                if (dlSel) decisions.datalensOption = dlSel.value;
                var ddCheck = document.getElementById('dueDiligenceCheck');
                if (ddCheck) decisions.dueDiligence = ddCheck.checked;
                var mlCheck = document.getElementById('hireMLCheck');
                if (mlCheck) decisions.hireML = mlCheck.checked;
                var expCheck = document.getElementById('explainabilityCheck');
                if (expCheck) decisions.explainability = expCheck.checked;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;
            var investment = 0;
            var revenueImpact = 0;
            var capacityImpact = 0;
            var description = '';
            var score = 0;

            if (round === 1) {
                investment = d.frameworkBudget;
                if (d.platformTeam) investment += 1.2;
                ds.cash -= investment;
                ds.investmentTotal += investment;

                if (d.scalingModel === 'custom') {
                    ds.doraComposite += 15;
                    ds.velocityMultiplier += 0.12;
                    revenueImpact = 8;
                    score = 85;
                    description = this._t('desc_custom');
                } else if (d.scalingModel === 'safe') {
                    ds.doraComposite += 10;
                    ds.velocityMultiplier += 0.08;
                    revenueImpact = 5;
                    score = d.frameworkBudget >= 4 ? 70 : 55;
                    description = this._t('desc_safe');
                    if (d.frameworkBudget < 4) {
                        ds.velocityMultiplier -= 0.03;
                    }
                } else {
                    ds.doraComposite += 8;
                    ds.velocityMultiplier += 0.05;
                    revenueImpact = 3;
                    score = 50;
                    description = this._t('desc_spotify');
                }

                if (d.platformTeam) {
                    ds.doraComposite += 5;
                    ds.velocityMultiplier += 0.04;
                    score += 10;
                }

                if (d.doraTarget === 'mttr') {
                    ds.doraComposite += 4;
                    score += 5;
                } else if (d.doraTarget === 'change_fail') {
                    ds.doraComposite += 3;
                    score += 4;
                } else {
                    ds.doraComposite += 2;
                    score += 2;
                }

                ds.revenueRunRate += revenueImpact;
                capacityImpact = 0;

            } else if (round === 2) {
                if (d.gammaOption === 'A') {
                    investment = 2.8;
                    ds.sdkDelayMonths = 3;
                    ds.velocityMultiplier -= 0.05;
                    revenueImpact = -4;
                    score = 45;
                    description = this._t('desc_gamma_a');
                } else if (d.gammaOption === 'B') {
                    investment = 0;
                    ds.sdkDelayMonths = 3;
                    revenueImpact = 10;
                    score = 75;
                    description = this._t('desc_gamma_b');
                    ds.sdkStatus = 'v4.0-lite';
                } else if (d.gammaOption === 'C') {
                    investment = 1.1;
                    ds.sdkDelayMonths = 4;
                    revenueImpact = 6;
                    score = 65;
                    description = this._t('desc_gamma_c');
                } else {
                    investment = 8.4;
                    ds.sdkDelayMonths = 0;
                    revenueImpact = 14;
                    score = 60;
                    description = this._t('desc_gamma_d');
                    ds.sdkStatus = 'outsourced';
                }

                if (d.marianaAction === 'rotate') {
                    ds.marianaRetained = true;
                    ds.velocityMultiplier += 0.03;
                    score += 15;
                } else if (d.marianaAction === 'retain') {
                    investment += 0.36;
                    ds.marianaRetained = true;
                    score += 8;
                } else {
                    var attritionRoll = Math.random();
                    if (attritionRoll < 0.65) {
                        ds.marianaRetained = false;
                        investment += 3.2;
                        ds.velocityMultiplier -= 0.06;
                        score -= 10;
                    } else {
                        ds.marianaRetained = true;
                    }
                }

                if (d.testCoverageSprint) {
                    ds.sdkDelayMonths += 0.5;
                    ds.techDebtScore += 6;
                    ds.velocityMultiplier += 0.05;
                    score += 8;
                }

                ds.cash -= investment;
                ds.investmentTotal += investment;
                ds.revenueRunRate += revenueImpact;
                capacityImpact = d.gammaOption === 'D' ? 18 : 0;

            } else if (round === 3) {
                var total = d.allocReg + d.allocDebt + d.allocSdk + d.allocRoadmap + d.allocBau;
                capacityImpact = total;

                var regCost = d.allocReg >= 38 ? 17.8 : 17.8 * (d.allocReg / 38);
                investment = regCost;

                if (d.allocDebt >= 16) {
                    var velGain = 0.20;
                    ds.velocityMultiplier += velGain;
                    ds.techDebtScore += 18;
                    investment += 4.8;
                    score += 30;
                } else if (d.allocDebt >= 8) {
                    ds.velocityMultiplier += 0.10;
                    ds.techDebtScore += 10;
                    investment += 2.4;
                    score += 15;
                }

                if (d.allocReg >= 38) {
                    ds.regulatoryCompliance = 100;
                    score += 25;
                } else {
                    ds.regulatoryCompliance = Math.round((d.allocReg / 38) * 100);
                    score -= 20;
                }

                if (d.allocSdk >= 18) {
                    ds.sdkDelayMonths = Math.max(0, ds.sdkDelayMonths - 3);
                    ds.sdkStatus = 'on-track';
                    score += 15;
                    revenueImpact = 14;
                } else if (d.allocSdk >= 10) {
                    ds.sdkDelayMonths = Math.max(0, ds.sdkDelayMonths - 1);
                    score += 8;
                    revenueImpact = 6;
                }

                var roadmapRevenue = d.allocRoadmap * 0.8;
                revenueImpact += roadmapRevenue;
                ds.revenueRunRate += revenueImpact;

                var slack = 346.8 - total;
                if (slack >= 20) score += 10;
                if (slack < 0) score -= 30;

                ds.cash -= investment;
                ds.investmentTotal += investment;
                description = this._t('desc_capacity') + ' ' + total.toFixed(0) + '/346.8 ' + this._t('eng_months_short');

            } else if (round === 4) {
                if (d.datalensOption === 'acquire') {
                    investment = 180;
                    ds.fraudLosses = 7.8;
                    ds.engineeringCapacity += 12;
                    revenueImpact = 22;
                    score = 40;
                    description = this._t('desc_acquire');
                    if (!d.dueDiligence) {
                        var riskRoll = Math.random();
                        if (riskRoll < 0.4) {
                            investment += 15.6;
                            score -= 30;
                        }
                    } else {
                        score += 15;
                    }
                } else if (d.datalensOption === 'build') {
                    investment = 4.2;
                    ds.fraudLosses = 12.4;
                    revenueImpact = -6;
                    score = 30;
                    description = this._t('desc_build');
                } else {
                    investment = 3.4;
                    ds.fraudLosses = 9.2;
                    ds.engineeringCapacity += 6;
                    revenueImpact = 12;
                    score = 75;
                    description = this._t('desc_partner');
                    if (d.dueDiligence) score += 10;
                }

                if (d.hireML) {
                    investment += 2.4;
                    ds.velocityMultiplier += 0.03;
                    score += 10;
                }

                if (d.explainability) {
                    investment += 0.6;
                    ds.regulatoryCompliance = Math.min(100, ds.regulatoryCompliance + 5);
                    score += 8;
                }

                ds.cash -= investment;
                ds.investmentTotal += investment;
                ds.revenueRunRate += revenueImpact;
                capacityImpact = 0;
            }

            ds.cashHistory.push(ds.cash);
            ds.revenueHistory.push(ds.revenueRunRate);
            ds.capacityUsed.push(capacityImpact);
            ds.capacityRemaining.push(Math.max(0, ds.engineeringCapacity - capacityImpact));

            // Persist normalized 0-100 grade to the framework grading contract.
            // Server reads domainState.performance.overallScore (results_utils.php::express_resolveDomainScore).
            // Recomputed from full history each period -> undo-safe (never accumulated).
            var roundScore = Math.max(0, Math.min(100, score));
            var priorScores = (state.history || []).map(function(h) {
                return (h && h.results && typeof h.results.score === 'number') ? h.results.score : 0;
            });
            priorScores.push(roundScore);
            var overall = Math.round(priorScores.reduce(function(a, b) { return a + b; }, 0) / priorScores.length);
            ds.performance = ds.performance || {};
            ds.performance.overallScore = overall;
            ds.performance.roundScores = priorScores;
            ds.performance.grade = overall >= 90 ? 'A' : overall >= 80 ? 'B' : overall >= 70 ? 'C' : overall >= 60 ? 'D' : 'F';
            ds.performance.performanceTier = overall >= 75 ? 'visionary' : overall >= 60 ? 'strategic' : overall >= 45 ? 'competent' : 'developing';

            var self = this;
            if (round < this.ROUNDS.length) {
                setTimeout(function() {
                    self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
                }, 500);
            }

            return {
                period: round,
                description: description,
                investment: Math.round(investment * 10) / 10,
                revenueImpact: Math.round(revenueImpact * 10) / 10,
                capacityImpact: Math.round(capacityImpact * 10) / 10,
                cash: Math.round(ds.cash * 10) / 10,
                revenueRunRate: Math.round(ds.revenueRunRate * 10) / 10,
                techDebtScore: ds.techDebtScore,
                doraComposite: ds.doraComposite,
                score: roundScore,
                marianaRetained: ds.marianaRetained,
                regulatoryCompliance: ds.regulatoryCompliance,
                sdkStatus: ds.sdkStatus
            };
        }

