        getPerformanceSummary(history) {
            if (!history.length) return {};
            var scores = history.map(function(r) { return r.results ? r.results.score || 0 : 0; });
            var totalScore = scores.reduce(function(s, v) { return s + v; }, 0);
            var avgScore = totalScore / scores.length;
            var lastCash = history[history.length - 1].results ? history[history.length - 1].results.cash : 0;
            var lastRevenue = history[history.length - 1].results ? history[history.length - 1].results.revenueRunRate : 0;
            var lastRegCompliance = history[history.length - 1].results ? history[history.length - 1].results.regulatoryCompliance : 0;
            var marianaKept = history[history.length - 1].results ? history[history.length - 1].results.marianaRetained : false;

            var performance = this._t('perf_developing');
            if (avgScore >= 75) performance = this._t('perf_visionary');
            else if (avgScore >= 60) performance = this._t('perf_strategic');
            else if (avgScore >= 45) performance = this._t('perf_competent');

            var insights = [];
            insights.push(this._t(lastRevenue >= 400 ? 'insight_rev_strong' : 'insight_rev_short'));
            insights.push(this._t(lastRegCompliance >= 100 ? 'insight_reg_full' : 'insight_reg_gap'));
            insights.push(this._t(marianaKept ? 'insight_mariana_kept' : 'insight_mariana_lost'));
            insights.push(this._t(lastCash > 200 ? 'insight_cash_healthy' : 'insight_cash_tight'));

            return {
                totalPeriods: history.length,
                totalScore: totalScore,
                avgScore: Math.round(avgScore),
                overallScore: Math.round(avgScore),
                performance: performance,
                finalRevenue: lastRevenue,
                finalCash: lastCash,
                regulatoryCompliance: lastRegCompliance,
                marianaKept: marianaKept,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            if (!summary || typeof summary.avgScore !== 'number') {
                return '<div class="agil-debrief"><p>' + this._t('debrief_title') + '</p></div>';
            }
            var t = this._t.bind(this);
            var score = summary.avgScore;
            var tier = score >= 75 ? 'visionary' : score >= 60 ? 'strategic' : score >= 45 ? 'competent' : 'developing';
            var money = function(v) { return 'MXN ' + Math.round(v || 0) + 'M'; };
            var kpis = [
                { label: t('debrief_kpi_revenue'), value: money(summary.finalRevenue) },
                { label: t('debrief_kpi_cash'), value: money(summary.finalCash) },
                { label: t('debrief_kpi_reg'), value: Math.round(summary.regulatoryCompliance || 0) + '%' },
                { label: t('debrief_kpi_talent'), value: summary.marianaKept ? t('debrief_retained') : t('debrief_lost') }
            ];
            var kpiHtml = kpis.map(function(k) {
                return '<div class="agil-debrief-kpi"><div class="agil-debrief-kpi-label">' + k.label +
                       '</div><div class="agil-debrief-kpi-value">' + k.value + '</div></div>';
            }).join('');
            var insightsHtml = (summary.insights || []).map(function(x) { return '<li>' + x + '</li>'; }).join('');
            return '' +
                '<div class="agil-debrief agil-debrief-tier-' + tier + '">' +
                    '<div class="agil-debrief-scorewrap">' +
                        '<div class="agil-debrief-score">' + score + '<span class="agil-debrief-score-max">/100</span></div>' +
                        '<div class="agil-debrief-verdict">' + (summary.performance || '') + '</div>' +
                    '</div>' +
                    '<div class="agil-debrief-kpis">' + kpiHtml + '</div>' +
                    (insightsHtml ? ('<div class="agil-debrief-insights"><h4>' + t('debrief_insights') + '</h4><ul>' + insightsHtml + '</ul></div>') : '') +
                '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            var round = results.period;
            if (round === 1 && results.score < 60) return window.mySimulation.t('hint_r1_low');
            if (round === 2 && !results.marianaRetained) return window.mySimulation.t('hint_mariana_lost');
            if (round === 2 && results.score >= 70) return window.mySimulation.t('hint_r2_good');
            if (round === 3 && results.regulatoryCompliance < 100) return window.mySimulation.t('hint_reg_gap');
            if (round === 3 && results.capacityImpact > 300) return window.mySimulation.t('hint_overalloc');
            if (round === 4 && results.score >= 70) return window.mySimulation.t('hint_r4_good');
            if (round === 4 && results.score < 40) return window.mySimulation.t('hint_r4_low');
            return null;
        }

