        _lang() {
            try {
                var s = window.mySimulation;
                if (s && s.language) return s.language;
                if (s && s.currentLanguage) return s.currentLanguage;
                var hl = (document.documentElement && document.documentElement.lang) || '';
                if (hl) return hl.slice(0, 2).toLowerCase();
            } catch (e) {}
            return 'en';
        }

        _t(key) {
            try {
                if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                    return window.mySimulation.t(key);
                }
            } catch (e) {}
            return key;
        }

        _sdkLabel(code) {
            var map = { 'delayed': 'sdk_delayed', 'v4.0-lite': 'sdk_lite', 'outsourced': 'sdk_outsourced', 'on-track': 'sdk_ontrack' };
            return this._t(map[code] || 'sdk_delayed');
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            var lang = this._lang();
            if (briefEl) {
                briefEl.innerHTML = lang === 'es' ? round.descEs : round.descEn;
            }

            var roundNameEl = document.getElementById('roundNameDisplay');
            if (roundNameEl) {
                var nameKey = 'round' + (idx + 1) + '_name';
                if (window.mySimulation && window.mySimulation.t) {
                    roundNameEl.textContent = '— ' + window.mySimulation.t(nameKey);
                } else {
                    roundNameEl.textContent = '— ' + (lang === 'es' ? round.nameEs : round.nameEn);
                }
            }

            var panels = ['round1Panel', 'round2Panel', 'round3Panel', 'round4Panel'];
            for (var i = 0; i < panels.length; i++) {
                var panel = document.getElementById(panels[i]);
                if (panel) panel.style.display = (i === idx) ? 'block' : 'none';
            }

            if (idx === 2) {
                this._setupAllocListeners();
            }
        }

        _setupAllocListeners() {
            var self = this;
            var ids = ['allocRegInput', 'allocDebtInput', 'allocSdkInput', 'allocRoadmapInput', 'allocBauInput'];
            var updateTotal = function() {
                var total = 0;
                for (var i = 0; i < ids.length; i++) {
                    var el = document.getElementById(ids[i]);
                    if (el) total += parseFloat(el.value) || 0;
                }
                var display = document.getElementById('totalAllocDisplay');
                if (display) {
                    display.textContent = total.toFixed(1);
                    display.style.color = total > 346.8 ? '#ef4444' : total > 300 ? '#f59e0b' : '#10b981';
                }
            };
            for (var i = 0; i < ids.length; i++) {
                var el = document.getElementById(ids[i]);
                if (el && !el.dataset.listenerAttached) {
                    el.addEventListener('input', updateTotal);
                    el.dataset.listenerAttached = 'true';
                }
            }
            updateTotal();
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new AgilAdapter(), {
            simulationType: 'el_agil',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

